{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "Accept in principle only if fundamental, tax and indemnity claims sit outside it. Negotiate the figure."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Tipping (first-dollar) basket, lower de minimis, aggregation of related claims"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PARTIAL",
      "evidence": "Accept if carve-outs are right. Tax should be 5 to 7 years. Fundamental and IP claims need longer."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title, capacity and tax outside the general cap and time limits (cap at price, 6 years or more)."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Carve out fraud, wilful concealment, indemnities, covenants, fundamental and tax claims."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Specific, fair disclosure only, with enough detail to identify the matter. No disclosure against fundamental, tax, or indemnity claims."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Specific-only disclosure, and deletion of cl 8.3's constructive knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Bluefen consent as a Buyer-benefit condition precedent, unconditional or on terms satisfactory to you."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Riverlark repaid at Completion from the price, with all security discharges delivered at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "DD-005 bonuses and on-costs deducted from the price as Seller costs, and shown in the funds flow."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Ironquay payment verified and a confirmatory assignment delivered pre-Completion, with a broad IP indemnity not limited to AUD 180,000."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Specific uncapped (or separately capped) indemnity for the DD-006 incident, with investigation and notification completed first."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Add a conduct-of-business covenant requiring Buyer consent for renewals before Completion."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reverse it: limitations apply only to general warranty claims and exclusions must be express"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Verify with ASIC extracts, constitution, any shareholders' agreement, options or pre-emption rights, PPSR searches, and share transfer forms and certificates."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "The Seller says these are \"settled under the general regime\". They are not."
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "Within the market range for general claims, but it is applied to everything",
  "names_manipulation": true
}

